describe("getTag – self-closing", () => {
  it("returns content and empty innerContent for <tag />", () => {
    expect(getTag("<my-nav />", "my-nav")).toEqual({
      content: "<my-nav />",
      innerContent: "",
    });
  });

  it("returns content and empty innerContent for <tag/> (no space)", () => {
    expect(getTag("<my-nav/>", "my-nav")).toEqual({
      content: "<my-nav/>",
      innerContent: "",
    });
  });

  it("returns content and empty innerContent for self-closing with attributes", () => {
    expect(getTag('<my-nav class="main" />', "my-nav")).toEqual({
      content: '<my-nav class="main" />',
      innerContent: "",
    });
  });

  it("still handles paired tags (regression)", () => {
    expect(getTag("<my-nav>inner</my-nav>", "my-nav")).toEqual({
      content: "<my-nav>inner</my-nav>",
      innerContent: "inner",
    });
  });
});

describe("replaceTag – self-closing", () => {
  it("replaces a self-closing tag", () => {
    expect(replaceTag("<div><my-nav /></div>", "my-nav", "<nav></nav>")).toBe(
      "<div><nav></nav></div>",
    );
  });

  it("replaces a self-closing tag without space before slash", () => {
    expect(replaceTag("<div><my-nav/></div>", "my-nav", "<nav></nav>")).toBe(
      "<div><nav></nav></div>",
    );
  });

  it("replaces self-closing with attributes", () => {
    expect(
      replaceTag('<div><my-nav class="x" /></div>', "my-nav", "<nav></nav>"),
    ).toBe("<div><nav></nav></div>");
  });

  it("still replaces paired tags (regression)", () => {
    expect(
      replaceTag(
        "<div><my-nav>inner</my-nav></div>",
        "my-nav",
        "<nav>inner</nav>",
      ),
    ).toBe("<div><nav>inner</nav></div>");
  });
});

describe("getFirstComponent – self-closing", () => {
  const componentList = {
    "my-nav": {
      fileName: "components/my-nav.html",
      fileContent: "<nav><ul><li>Home</li></ul></nav>",
    },
  };

  it("finds a self-closing component", () => {
    const result = getFirstComponent("<div><my-nav /></div>", componentList);
    expect(result.name).toBe("my-nav");
    expect(result.content).toBe("<my-nav />");
    expect(result.innerContent).toBe("");
  });
});

