describe("extractNamedSlotContent", () => {
  it("extracts a single named slot", () => {
    const inner = '<div data-bascik-slot="header"><h1>My Header</h1></div>';
    expect(extractNamedSlotContent(inner)).toEqual({
      header: "<h1>My Header</h1>",
    });
  });

  it("extracts multiple named slots", () => {
    const inner =
      '<div data-bascik-slot="header"><h1>H</h1></div>' +
      '<div data-bascik-slot="footer"><p>F</p></div>';
    expect(extractNamedSlotContent(inner)).toEqual({
      header: "<h1>H</h1>",
      footer: "<p>F</p>",
    });
  });

  it("returns empty object when no named slots", () => {
    expect(extractNamedSlotContent("<p>just content</p>")).toEqual({});
  });

  it("returns empty object for empty string", () => {
    expect(extractNamedSlotContent("")).toEqual({});
  });

  it("handles nested same-tag elements inside slot wrapper", () => {
    // The slot wrapper is a <div>. The content also contains a <div>.
    // The regex must close at the OUTER </div>, not the first inner one.
    const inner =
      '<div data-bascik-slot="example">' +
      "<p>Before</p><div style=\"nested\"><span>Inner</span></div><p>After</p>" +
      "</div>";
    expect(extractNamedSlotContent(inner)).toEqual({
      example: "<p>Before</p><div style=\"nested\"><span>Inner</span></div><p>After</p>",
    });
  });

  it("handles deeply nested same-tag elements", () => {
    const inner =
      '<div data-bascik-slot="x">' +
      "<div><div><p>deep</p></div></div>" +
      "</div>" +
      '<div data-bascik-slot="y"><span>y</span></div>';
    expect(extractNamedSlotContent(inner)).toEqual({
      x: "<div><div><p>deep</p></div></div>",
      y: "<span>y</span>",
    });
  });

  it("extracts a slot whose marker is preceded by other attributes", () => {
    const inner =
      '<div id="header-slot" data-bascik-slot="header"><h1>Custom Header</h1></div>';
    expect(extractNamedSlotContent(inner)).toEqual({
      header: "<h1>Custom Header</h1>",
    });
  });

  it("ignores the marker text inside a quoted attribute value", () => {
    const inner =
      "<p title='see data-bascik-slot=\"fake\" usage'>text</p>";
    expect(extractNamedSlotContent(inner)).toEqual({});
  });
});

describe("replaceNamedSlots", () => {
  it("replaces a named slot placeholder with provided content", () => {
    const template =
      '<footer><div data-bascik-slot="footer-links"></div></footer>';
    const slots = { "footer-links": "<a href='/'>Home</a>" };
    expect(replaceNamedSlots(template, slots)).toBe(
      "<footer><a href='/'>Home</a></footer>",
    );
  });

  it("removes an unfilled named slot placeholder", () => {
    const template =
      '<footer><div data-bascik-slot="footer-links"></div></footer>';
    expect(replaceNamedSlots(template, {})).toBe("<footer></footer>");
  });

  it("does not affect default data-bascik-slot", () => {
    const template =
      "<div><div data-bascik-slot></div>" +
      '<span data-bascik-slot="side"></span></div>';
    const slots = { side: "<p>sidebar</p>" };
    const result = replaceNamedSlots(template, slots);
    expect(result).toContain("<div data-bascik-slot></div>");
    expect(result).toContain("<p>sidebar</p>");
  });

  it("matches a marker preceded by other attributes", () => {
    const template =
      '<footer><div id="nav-slot" data-bascik-slot="navigation"><p>Default nav</p></div></footer>';
    expect(
      replaceNamedSlots(template, { navigation: "<nav>Menu</nav>" }),
    ).toBe("<footer><nav>Menu</nav></footer>");
  });

  it("keeps fallback content containing nested same-tag elements intact", () => {
    const template =
      '<section><div data-bascik-slot="x"><div>fallback</div></div></section>';
    expect(replaceNamedSlots(template, {})).toBe(
      "<section><div>fallback</div></section>",
    );
  });

  it("replaces a placeholder whose fallback has nested same-tag elements", () => {
    const template =
      '<section><div data-bascik-slot="x"><div>fallback</div></div></section>';
    expect(replaceNamedSlots(template, { x: "<p>filled</p>" })).toBe(
      "<section><p>filled</p></section>",
    );
  });
});

describe("replaceDefaultSlots", () => {
  it("replaces a default slot marker with provided content", () => {
    const template = "<div><div data-bascik-slot></div></div>";
    expect(replaceDefaultSlots(template, "<p>content</p>")).toBe(
      "<div><p>content</p></div>",
    );
  });

  it("keeps fallback content when no content is provided", () => {
    const template = "<div><div data-bascik-slot><p>fallback</p></div></div>";
    expect(replaceDefaultSlots(template, "")).toBe("<div><p>fallback</p></div>");
  });

  it("matches a marker preceded by other attributes", () => {
    const template =
      '<div><div class="card-body" data-bascik-slot><p>fallback</p></div></div>';
    expect(replaceDefaultSlots(template, "<p>custom</p>")).toBe(
      "<div><p>custom</p></div>",
    );
  });

  it("balances nested same-tag elements inside the fallback", () => {
    const template =
      "<section><div data-bascik-slot><div>fallback</div></div></section>";
    expect(replaceDefaultSlots(template, "<p>filled</p>")).toBe(
      "<section><p>filled</p></section>",
    );
    expect(replaceDefaultSlots(template, "")).toBe(
      "<section><div>fallback</div></section>",
    );
  });

  it("does not touch named slot markers", () => {
    const template =
      '<div><span data-bascik-slot="side"><p>side fallback</p></span></div>';
    expect(replaceDefaultSlots(template, "<p>content</p>")).toBe(template);
  });
});

describe("extractDefaultSlotContent", () => {
  it("strips named slot wrappers, keeping remaining content", () => {
    const inner =
      '<p>body</p><div data-bascik-slot="sidebar"><nav>nav</nav></div>';
    expect(extractDefaultSlotContent(inner)).toBe("<p>body</p>");
  });

  it("returns full content when there are no named slot wrappers", () => {
    expect(extractDefaultSlotContent("<p>content</p>")).toBe("<p>content</p>");
  });

  it("returns empty string for empty input", () => {
    expect(extractDefaultSlotContent("")).toBe("");
  });

  it("strips multiple named slot wrappers", () => {
    const inner =
      "<p>main</p>" +
      '<div data-bascik-slot="a"><span>a</span></div>' +
      '<div data-bascik-slot="b"><span>b</span></div>';
    expect(extractDefaultSlotContent(inner)).toBe("<p>main</p>");
  });

  it("strips named slot wrapper containing nested same-tag elements", () => {
    // Slot wrapper is <div>. Content has inner <div>s — must strip whole wrapper.
    const inner =
      "<p>default</p>" +
      '<div data-bascik-slot="side"><div style="inner"><span>s</span></div></div>';
    expect(extractDefaultSlotContent(inner)).toBe("<p>default</p>");
  });

  it("trims surrounding whitespace from slot content", () => {
    expect(extractDefaultSlotContent("\n  code here\n")).toBe("code here");
  });

  it("trims whitespace left after named slot wrappers are removed", () => {
    const inner =
      "\n  <p>main</p>\n  " +
      '<div data-bascik-slot="a"><span>a</span></div>' +
      "\n";
    expect(extractDefaultSlotContent(inner)).toBe("<p>main</p>");
  });
});

